import java.util.*;

public class Main {
    static long INF = (long) 1e18;
    static long ans = 0;
    static int[] dpr;

    static int solve(long n) {
        if (n == 0) return 0;
        if (n < dpr.length && dpr[(int) n] != 0) return dpr[(int) n];
        long lastdif = INF;
        long x = 1;
        int i = 0;
        while (Math.abs(x - n) <= lastdif) {
            lastdif = Math.abs(x - n);
            x = x * 10 + 1;
            i++;
        }
        x /= 10;
        if (x > n && x / 10 != 0) {
            if (n < dpr.length) {
                int res1 = i + solve(Math.abs(x - n));
                int res2 = i - 1 + solve(Math.abs(x / 10 - n));
                int result = Math.min(res1, res2);
                if (n < dpr.length) dpr[(int) n] = result;
                return result;
            } else {
                return Math.min(i + solve(Math.abs(x - n)), i - 1 + solve(Math.abs(x / 10 - n)));
            }
        }
        if (n < dpr.length) {
            int result = i + solve(Math.abs(x - n));
            dpr[(int) n] = result;
            return result;
        }
        return i + solve(Math.abs(x - n));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        dpr = new int[10000000];
        System.out.println(solve(n));
        sc.close();
    }
}
